        elif self.dequeue_stack.is_empty():
            # Transfer elements from enqueue stack to dequeue stack if needed
            while not self.enqueue_stack.is_empty():
                self.dequeue_stack.push(self.enqueue_stack.pop())

        return self.dequeue_stack.pop()  # Return and remove item from dequeue stack

    def is_empty(self):
        return self.enqueue_stack.is_empty() and self.dequeue_stack.is_empty()


# Example usage
queue = QueueUsingTwoStacks()

# Enqueue operations
queue.enqueue(10)
queue.enqueue(20)
queue.enqueue(30)

print("Front element:", queue.dequeue())  # Output: 10
print("Queue after dequeue:", queue)  # Output: dequeue_stack=[20], enqueue_stack=[30]

queue.enqueue(40)
print("Current queue:", queue)  # Output: dequeue_stack=[20], enqueue_stack=[30, 40]

print("Dequeued items:", end=" ")
while not queue.is_empty():
    print(queue.dequeue(), end=" ")  # Output: 20 30 40
print()
